UpdateIf(
    colGridOperatorFormValidation,
    Name = "GridExpansionRequired",
    {
        Valid:  true,
        Dirty: true
    }
);

UpdateIf(
    colGridOperatorFormValidation,
    Name = "GridVoltage",
    {
        Valid: And(
            Not(IsBlank(txt_GridOperator_DisplayProjectBodyRightContent_GridVoltage.Value)),
            IsNumeric(txt_GridOperator_DisplayProjectBodyRightContent_GridVoltage.Value)
        ),
        Dirty: true
    }
);

// Amount is not blank, is numeric and does not contain comma (dot should be used instead)
And(
    Not(IsBlank(txt_GridOperator_DisplayProjectBodyRightContent_GridVoltage.Value)), 
    Or(
        Not(IsNumeric(txt_GridOperator_DisplayProjectBodyRightContent_GridVoltage.Value)),
        IsMatch(txt_GridOperator_DisplayProjectBodyRightContent_GridVoltage.Value, ",", MatchOptions.Contains)
    )
)

